-- Align names on the production DB with the names Drizzle generates.
-- Seven tables were first created by hand-written SQL, so Postgres picked its
-- own names (`*_fkey`, `*_pkey`, lower-case index names). Future migrations
-- generated by drizzle-kit refer to the Drizzle names, so they must match.
-- On a fresh DB built from 0001 the old names do not exist: every rename below
-- is skipped. Only names change; no data, no structure.
-- Also: `order.discount_percent` default was set as `0` (integer) by hand;
-- Drizzle writes '0' (numeric). Same value, aligned so both DBs are identical.

DO $$
DECLARE
  r record;
BEGIN
  FOR r IN SELECT * FROM (VALUES
    ('card_contact', 'card_contact_card_id_fkey', 'card_contact_card_id_card_id_fk'),
    ('card_contact', 'card_contact_contact_id_fkey', 'card_contact_contact_id_contact_id_fk'),
    ('deal_activity', 'deal_activity_actor_user_id_fkey', 'deal_activity_actor_user_id_user_id_fk'),
    ('deal_activity', 'deal_activity_deal_id_fkey', 'deal_activity_deal_id_deal_id_fk'),
    ('deal_activity', 'deal_activity_from_stage_id_fkey', 'deal_activity_from_stage_id_deal_funnel_stage_id_fk'),
    ('deal_activity', 'deal_activity_to_stage_id_fkey', 'deal_activity_to_stage_id_deal_funnel_stage_id_fk'),
    ('discovery_blocklist', 'discovery_blocklist_created_by_user_id_fkey', 'discovery_blocklist_created_by_user_id_user_id_fk'),
    ('discovery_blocklist', 'discovery_blocklist_organization_id_fkey', 'discovery_blocklist_organization_id_organization_id_fk'),
    ('notification_read_state', 'notification_read_state_organization_id_fkey', 'notification_read_state_organization_id_organization_id_fk'),
    ('notification_read_state', 'notification_read_state_user_id_fkey', 'notification_read_state_user_id_user_id_fk'),
    ('notification_read_state', 'notification_read_state_pkey', 'notification_read_state_organization_id_user_id_pk'),
    ('org_identity_entry', 'org_identity_entry_created_by_user_id_fkey', 'org_identity_entry_created_by_user_id_user_id_fk'),
    ('org_identity_entry', 'org_identity_entry_organization_id_fkey', 'org_identity_entry_organization_id_organization_id_fk'),
    ('product_alias', 'product_alias_organization_id_fkey', 'product_alias_organization_id_organization_id_fk'),
    ('teardown_log', 'teardown_log_admin_user_id_fkey', 'teardown_log_admin_user_id_user_id_fk'),
    ('teardown_log', 'teardown_log_organization_id_fkey', 'teardown_log_organization_id_organization_id_fk')
  ) AS t(tbl, old_name, new_name)
  LOOP
    IF EXISTS (
      SELECT 1 FROM pg_constraint c
      JOIN pg_class k ON k.oid = c.conrelid
      JOIN pg_namespace n ON n.oid = k.relnamespace
      WHERE n.nspname = 'public' AND k.relname = r.tbl AND c.conname = r.old_name
    ) THEN
      EXECUTE format('ALTER TABLE public.%I RENAME CONSTRAINT %I TO %I', r.tbl, r.old_name, r.new_name);
    END IF;
  END LOOP;
END $$;
--> statement-breakpoint
ALTER INDEX IF EXISTS public.card_contact_contactid_idx RENAME TO "card_contact_contactId_idx";
--> statement-breakpoint
ALTER INDEX IF EXISTS public.discovery_blocklist_organizationid_idx RENAME TO "discovery_blocklist_organizationId_idx";
--> statement-breakpoint
ALTER INDEX IF EXISTS public.org_identity_entry_organizationid_idx RENAME TO "org_identity_entry_organizationId_idx";
--> statement-breakpoint
ALTER TABLE public."order" ALTER COLUMN discount_percent SET DEFAULT '0';
